function f(h,i,c,m,n=6){const t=Math.max(0,h|0),a=Math.max(1,i|0),M=t*a;if(t===0)return{start:0,end:0,offsetTop:0,totalHeight:0,visibleCount:0};const s=Math.ceil(Math.max(0,m)/a)+n*2,r=Math.max(0,t-Math.max(1,s)),x=Math.floor(Math.max(0,c)/a)-n,o=Math.min(r,Math.max(0,x)),e=Math.min(t,o+Math.max(1,s));return{start:o,end:e,offsetTop:o*a,totalHeight:M,visibleCount:e-o}}const l=30;export{l as V,f as c};
